export const bondAccrualDefinitions={
 bondAccruedCash:{title:'Reconcile an invented coupon-bond settlement with the next coupon and a sale',fields:[
  ['accrualFace','Bond face amount (CAD)',10000,1000,1000000,1000],
  ['accrualCoupon','Annual coupon rate, paid in two equal instalments (%)',4,0,10,.5],
  ['accrualEntryQuote','Executed clean purchase price per CAD 100 face',98.5,50,130,.5],
  ['accrualElapsedDay','Completed days in an invented 180-day period at settlement',90,0,179,1],
  ['accrualBuyFee','Separate purchase fee paid in cash (CAD)',10,0,100,5],
  ['accrualExitQuote','Assumed clean sale price just after the next coupon, per CAD 100 face',98.5,50,130,.5],
  ['accrualSellFee','Separate sale fee paid in cash (CAD)',10,0,100,5]
 ]}
};
export function bondAccrualPlan(d){
 const coupon=d.accrualFace*d.accrualCoupon/200,clean=d.accrualFace*d.accrualEntryQuote/100,accrued=coupon*d.accrualElapsedDay/180,dirty=clean+accrued,purchaseCash=dirty+d.accrualBuyFee,exitClean=d.accrualFace*d.accrualExitQuote/100,saleCash=exitClean-d.accrualSellFee,priceChange=exitClean-clean,holdingCoupon=coupon-accrued;
 const step=Math.max(1,Math.ceil((180-d.accrualElapsedDay)/18)),rows=[];
 for(let day=d.accrualElapsedDay;day<180;day+=step){
  const fraction=(day-d.accrualElapsedDay)/(180-d.accrualElapsedDay),cleanValue=clean+(exitClean-clean)*fraction,bondValue=cleanValue+coupon*day/180;
  rows.push({x:day,label:'Day '+day,bondChange:bondValue-dirty,couponCash:0,combinedChange:bondValue-dirty});
 }
 rows.push({x:180,label:'Day 180 · before coupon',bondChange:exitClean+coupon-dirty,couponCash:0,combinedChange:exitClean+coupon-dirty});
 rows.push({x:180,label:'Day 180 · after coupon, before sale',bondChange:exitClean-dirty,couponCash:coupon,combinedChange:exitClean+coupon-dirty});
 const rawResult=saleCash+coupon-purchaseCash;
 return {coupon,clean,accrued,dirty,purchaseCash,exitClean,saleCash,priceChange,holdingCoupon,remainingDays:180-d.accrualElapsedDay,rows,netResult:Math.abs(rawResult)<1e-8?0:rawResult};
}
export function bondAccrualResult(kind,d){
 if(kind!=='bondAccruedCash')throw Error('Unknown coupon-accrual topic.');
 const p=bondAccrualPlan(d);
 return {metrics:[['Cash required for dirty purchase price plus the separate fee',p.purchaseCash,'money'],['Full next coupon assumed received in cash',p.coupon,'money'],['Net cash result after that coupon and the assumed sale',p.netResult,'money']],note:'Original coupon-bond cash illustration. Annual coupon cash is split into two equal payments. The single coupon period has an invented 180-day denominator, with straight-line accrued coupon from day zero; it is not an Actual/Actual, Actual/365 or 30/360 market-convention calculation. The entered day is the settlement observation, not a trade-date settlement-rule calculation. The buyer is assumed entitled to the entire next coupon, paid in full on day 180, and sells the still-outstanding bond immediately afterward at the selected clean price. There is no maturity principal repayment. The quote path between those two selected prices is a linear teaching assumption, not a yield-based bond valuation or market forecast. Fees are separate cash charges. Embedded spreads, markdowns, default, ex-coupon trading, taxes, reinvestment, withholding and settlement delays are not calculated. The valuation chart excludes fees; both fees enter the final cash reconciliation exactly once. '+p.remainingDays+(p.remainingDays===1?' model day remains':' model days remain')+' until the coupon. Results are holding-period dollars, not yield to maturity, an annualized return or a product recommendation.',charts:[
  {id:'bond-accrual-settlement-bridge',type:'waterfall',title:'A clean quotation does not by itself identify the cash needed at settlement',unit:'money',rows:[{label:'Clean price multiplied by the face amount',value:p.clean},{label:'Accrued coupon paid with the purchase price',value:p.accrued},{label:'Separate purchase fee paid in cash',value:d.accrualBuyFee}],totalLabel:'Total purchase cash',note:'Dirty price is clean price plus accrued coupon in this example. The separate purchase fee is additional cash, rather than part of accrued interest. Face amount, quoted price per 100 and the final dollar payment have different roles.'},
  {id:'bond-accrual-coupon-transfer',type:'line',title:'The coupon moves value from the bond into cash without creating the whole payment as profit',unit:'money',unitLabel:'CAD changes from opening dirty bond value · fees excluded · before the sale',xLabel:'Day in model coupon period',xMin:d.accrualElapsedDay,series:[{name:'Change in bond value, including accrued coupon',rows:p.rows.map(r=>({x:r.x,label:r.label,value:r.bondChange}))},{name:'Coupon cash received after purchase',rows:p.rows.map(r=>({x:r.x,label:r.label,value:r.couponCash}))},{name:'Combined bond-plus-cash change',dash:true,rows:p.rows.map(r=>({x:r.x,label:r.label,value:r.combinedChange}))}],note:'Two observations share day 180: immediately before and immediately after coupon payment. The bond-value change falls by the full coupon and cash rises by the same amount, leaving the combined change unchanged at that event. Before the coupon, zero cash means the combined line overlaps the bond-change line. These are changes from the opening dirty value, not full balances; do not add the combined line to its components. The chart stops before the sale and excludes both fees.'},
  {id:'bond-accrual-result-bridge',type:'waterfall',title:'Reconcile the holding-period cash result after the assumed coupon and sale',unit:'money',rows:[{label:'Full next coupon received',value:p.coupon},{label:'Accrued coupon already paid in the purchase price',value:-p.accrued},{label:'Change between clean purchase and sale values',value:p.priceChange},{label:'Separate purchase fee',value:-d.accrualBuyFee},{label:'Separate sale fee',value:-d.accrualSellFee}],totalLabel:'Net holding-period cash result',note:'The same result equals sale proceeds after the sale fee plus the coupon, minus the entire purchase cash amount. Coupon cash less purchased accrued coupon is the selected holding-period coupon component; it is not a personal tax-income calculation. No face-value repayment is added to the sale proceeds.'},
  {id:'bond-accrual-timing-price-matrix',type:'heatmap',title:'A near coupon date does not eliminate accrued interest, dealing costs or sale-price risk',unit:'money',signed:true,unitLabel:'CAD net cash result · rows: elapsed settlement day; columns: clean sale quote per 100 face',columns:['96','98','100','102'],rows:[0,60,120,179].map(accrualElapsedDay=>({label:'Day '+accrualElapsedDay,values:[96,98,100,102].map(accrualExitQuote=>bondAccrualPlan({...d,accrualElapsedDay,accrualExitQuote}).netResult)})),note:'Cells retain face amount, annual coupon, clean purchase quote and both fees. They replace the settlement day and clean sale quote. Later settlement leaves fewer days to the same coupon and more accrued coupon in the purchase price. Cells therefore have different holding periods and are not annualized performance comparisons. None is assigned a probability or an executable market price.'}
 ]};
}
